// SVG ikon oluşturma yardımcısı
function icon(name, size = 20, className = '') {
  const svgContent = I[name];
  if (!svgContent) return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/></svg>`;
  return svgContent.replace('<svg', `<svg width="${size}" height="${size}" class="${className}"`);
}

function getIconList() { return Object.keys(I); }
function randomIcon() { const keys = Object.keys(I); return keys[Math.floor(Math.random() * keys.length)]; }

window.Icons = I;
window.icon = icon;

console.log('✅ Modern İkonlar yüklendi - ' + Object.keys(I).length + ' ikon');
